  line-height: 1.6;
  font-size: 16px;
}

main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
}

header {
  margin-bottom: 3rem;
  text-align: center;
}

h1 {
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 0.5rem;
}

h2 {
  font-size: 1.5rem;
  font-weight: 700;
}

p {
  color: var(--text-secondary);
}

.image-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
  margin-top: 2rem;
}

.image-item {
  display: flex;
  flex-direction: column;
  background-color: var(--bg-secondary);
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid var(--border);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.image-item:hover,
.image-item:focus-within {
  transform: translateY(-2px);
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
}

.image-item img {
  display: block;
  width: 100%;
  height: 200px;
  object-fit: cover;
  background-color: var(--bg-tertiary);
}

.image-item figcaption {
  padding: 1rem;
  font-weight: 500;
  color: var(--text-primary);
}

.delete-btn {
  margin: 0 1rem 1rem;
  padding: 0.75rem 1.5rem;
  background-color: var(--danger);
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease, outline 0.2s ease;
}

.delete-btn:hover {
  background-color: var(--danger-hover);
}

.delete-btn:focus {
  outline: 3px solid var(--focus-outline);
  outline-offset: 2px;
}

.delete-btn:active {
  transform: scale(0.98);
}

dialog {
  border: none;
  border-radius: 12px;
  background-color: var(--bg-secondary);
  color: var(--text-primary);
  padding: 0;
  max-width: 420px;
  width: 90vw;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

dialog::backdrop {
  background-color: var(--backdrop);
  backdrop-filter: blur(4px);
}

dialog h2 {
  padding: 1.5rem 1.5rem 0.5rem;
  margin-bottom: 0.5rem;
  color: var(--text-primary);
}

dialog p {
  padding: 0 1.5rem;
  margin-bottom: 1.5rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.dialog-actions {
  display: flex;
  gap: 1rem;
  padding: 1.5rem;
  background-color: var(--bg-tertiary);
  border-top: 1px solid var(--border);
  justify-content: flex-end;
}

.btn-cancel,
.btn-delete {
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: 6px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease, outline 0.2s ease;
}

.btn-cancel {
  background-color: var(--bg-secondary);
  color: var(--text-primary);
  border: 1px solid var(--border);
}

.btn-cancel:hover {
  background-color: var(--bg-tertiary);
}

.btn-cancel:focus {
  outline: 3px solid var(--focus-outline);
  outline-offset: 2px;
}

.btn-delete {
  background-color: var(--danger);
  color: white;
}

.btn-delete:hover {
  background-color: var(--danger-hover);
}

.btn-delete:focus {
  outline: 3px solid var(--focus-outline);
