AssistantMessageToolRequest(name='create', tool_call_id='tooluse_z28TAHz9Q0Lj9o6MOTjESK', arguments={'file_text': '(() => {
  const dialog = document.getElementById('delete-dialog');
  const triggers = document.querySelectorAll('.trigger');
  let currentTrigger = null;
  let currentImageName = '';

  triggers.forEach((trigger) => {
    trigger.addEventListener('click', () => {
      currentTrigger = trigger;
      const figcaption = trigger
        .closest('.image-item')
        ?.querySelector('figcaption');
      currentImageName = figcaption
        ? figcaption.textContent
        : 'the image';

      const heading = dialog.querySelector('h2');
      const ariaLabel = trigger.getAttribute('aria-label');

      if (ariaLabel) {
        heading.textContent = `Delete "${currentImageName}"?`;
      }

      dialog.showModal();
      const cancelBtn = dialog.querySelector('[data-close]');
      if (cancelBtn) {
        cancelBtn.focus();
      }
    });
  });

  const cancelBtn = dialog.querySelector('[data-close]');
  if (cancelBtn) {
    cancelBtn.addEventListener('click', () => {
      dialog.close('cancel');
    });
  }

  const confirmBtn = dialog.querySelector('[data-confirm]');
  if (confirmBtn) {
    confirmBtn.addEventListener('click', () => {
      dialog.close('delete');
    });
  }

  dialog.addEventListener('close', () => {
    if (dialog.returnValue === 'delete' && currentTrigger) {
      const imageItem = currentTrigger.closest('.image-item');
      if (imageItem) {
        imageItem.style.opacity = '0';
        imageItem.style.transform = 'scale(0.95)';
        setTimeout(() => {
          imageItem.remove();
        }, 300);
      }
    }

    if (currentTrigger && document.contains(currentTrigger)) {
      currentTrigger.focus();
    }

    currentTrigger = null;
    currentImageName = '';
  });

  dialog.addEventListener('cancel', () => {
    if (currentTrigger && document.contains(currentTrigger)) {
      currentTrigger.focus();
    }
    currentTrigger = null;
    currentImageName = '';
  });
})();
